const SEASONS=["2020","2021","2022","2023","2024","2025"];
const SN={2020:"20/21",2021:"21/22",2022:"22/23",2023:"23/24",2024:"24/25",2025:"25/26"};
let view="rankings",season="all",rMode=null,aMode="championship",bsMode="record",openIdx=null;

const fmt=n=>Number(n).toLocaleString("en-CA",{minimumFractionDigits:2,maximumFractionDigits:2});
const sy=y=>String(y).slice(-2);
const rv=(n,k)=>Number(RECORDS[n]?.[k]??0);

function makeRanks(key,hi=true){
  const s=Object.keys(RECORDS).map(n=>({n,v:rv(n,key)})).sort((a,b)=>hi?b.v-a.v:a.v-b.v);
  const r={};let lv=null,lr=0;s.forEach((x,i)=>{if(i===0||x.v!==lv){lr=i+1;lv=x.v;}r[x.n]=lr;});return r;
}
const RR={w:makeRanks("w"),l:makeRanks("l",false),pct:makeRanks("pct"),pm:makeRanks("pm")};

function recordText(obj){return `${obj?.w||0}-${obj?.l||0}-${obj?.t||0}`;}
function recordPct(obj){
  const w=Number(obj?.w||0), l=Number(obj?.l||0), t=Number(obj?.t||0), gp=w+l+t;
  return gp ? ((w + (t*.5)) / gp) * 100 : 0;
}
function teamSeasonRecord(name,yr){return SEASON_RECORDS.find(r=>r.franchise===name && String(r.year)===String(yr)) || {w:0,l:0,t:0};}
function summedRecordForTeam(name,scope){
  if(scope==="selected") return teamSeasonRecord(name,season);
  return SEASONS.reduce((a,y)=>{const r=teamSeasonRecord(name,y);a.w+=Number(r.w||0);a.l+=Number(r.l||0);a.t+=Number(r.t||0);return a;},{w:0,l:0,t:0});
}

function trophyImg(key, size) {
  const src = TROPHY_IMGS[key] || "";
  const h = size === "sm" ? 54 : 72;
  return src ? `<img src="${src}" style="height:${h}px;width:auto;object-fit:contain;filter:drop-shadow(0 3px 6px rgba(0,0,0,.8));">` : "";
}
function trophyItems(wins, key, size="") {
  if(!wins||!wins.length) return `<span class="tr-none">None</span>`;
  return wins.slice().sort((a,b)=>a.year>b.year?1:-1).map(w=>
    `<div class="tr">
      ${trophyImg(key, size)}
      <div class="tr-yr">'${sy(w.year)}</div>
      ${w.player?`<div class="tr-pl">${w.player}</div>`:""}
    </div>`
  ).join("");
}

function buildDrop(name){
  const ta=AWARDS[name]||{};
  const r=RECORDS[name]||{};
  const pm=r.pm>=0?"+"+r.pm:String(r.pm||0);

  // W/L Record strip — top
  const rrk=(k,lbl,val)=>{const rk=RR[k]?.[name];return `<div class="rec-cell"><div class="rec-val">${val}</div><div class="rec-lbl">${lbl}</div>${rk?`<div class="rec-rnk${rk===1?" gold":""}">#${rk}</div>`:""}</div>`;};
  const recStrip=`<div class="rec-strip">
    ${rrk("w","Wins",r.w||0)}${rrk("l","Losses",r.l||0)}
    <div class="rec-cell"><div class="rec-val">${r.t||0}</div><div class="rec-lbl">Ties</div></div>
    ${rrk("pct","Win %",(r.pct||0).toFixed(1)+"%")}${rrk("pm","+/-",pm)}
  </div>`;

  // Row 1: Championships — full width shelf
  const champRow=`
    <div class="drop-section">Championships</div>
    <div class="champ-row">
      <div class="award-items champ-items">${trophyItems(ta.championship,"championship")}</div>
    </div>`;

  // Row 2: Team awards — Wales + Clarence
  const teamRow=`
    <div class="drop-section">Team Awards</div>
    <div class="team-awards">
      <div class="award-col"><div class="award-col-name">Prince of Wales</div><div class="award-items">${trophyItems(ta.wales,"wales")}</div></div>
      <div class="award-col"><div class="award-col-name">Clarence Campbell</div><div class="award-items">${trophyItems(ta.clarence,"clarence")}</div></div>
    </div>`;

  // Row 3: Player awards
  const playerRow=`
    <div class="drop-section">Player Awards</div>
    <div class="player-awards">
      <div class="award-col-sm"><div class="award-col-sm-name">Hart</div><div class="award-items">${trophyItems(ta.hart,"hart","sm")}</div></div>
      <div class="award-col-sm"><div class="award-col-sm-name">Art Ross</div><div class="award-items">${trophyItems(ta.artross,"artross","sm")}</div></div>
      <div class="award-col-sm"><div class="award-col-sm-name">Vezina</div><div class="award-items">${trophyItems(ta.vezina,"vezina","sm")}</div></div>
      <div class="award-col-sm"><div class="award-col-sm-name">Calder Trophy</div><div class="award-items">${trophyItems(ta.calder,"calder","sm")}</div></div>
      <div class="award-col-sm"><div class="award-col-sm-name">Most FPS</div><div class="award-items">${trophyItems(ta.mvfp,"mvfp","sm")}</div></div>
    </div>`;

  const hist=HISTORY[name];
  const histHtml=hist&&hist.length>1?`<div class="hist">Franchise: ${hist.join(" → ")}</div>`:"";

  return recStrip+champRow+teamRow+playerRow+histHtml;
}

function getRows(){
  if(view==="bestseasons"){
    const rows=SEASON_RECORDS.map(r=>({
      ...r,
      rawPct:Number(r.pct||0),
      rawPts:Number(r.fpts||0)
    }));
    if(bsMode==="points"){
      return rows.sort((a,b)=>b.rawPts-a.rawPts || b.rawPct-a.rawPct || b.w-a.w).slice(0,10);
    }
    return rows.sort((a,b)=>b.rawPct-a.rawPct || b.w-a.w || a.l-b.l || b.rawPts-a.rawPts).slice(0,10);
  }

  if(view==="rankings"){
    if(rMode){
      if(rMode==="record"){
        const scope=season!=="all"?"selected":"all";
        const sub=season!=="all"?SN[season]:"All Time";
        return TEAMS.map(t=>{const r=summedRecordForTeam(t.name,scope), pct=recordPct(r);return {name:t.name,raw:pct,w:r.w,l:r.l,t:r.t,main:recordText(r),label:"Record",sub,seasonName:scope==="selected"?historicalSeasonName(t.name,season):""};}).sort((a,b)=>b.raw-a.raw || b.w-a.w || a.l-b.l || a.name.localeCompare(b.name));
      }
      const cfg={winpct:{key:"pct",lbl:"Win %",sub:"All Time Win %",hi:true},plusminus:{key:"pm",lbl:"+/-",sub:"Plus/Minus",hi:true}}[rMode];
      return Object.keys(RECORDS).map(n=>{const v=rv(n,cfg.key);return{name:n,main:cfg.key==="pct"?v.toFixed(1)+"%":cfg.key==="pm"?(v>=0?"+"+v:String(v)):String(v),label:cfg.lbl,sub:cfg.sub,raw:v};}).sort((a,b)=>cfg.hi?b.raw-a.raw:a.raw-b.raw);
    }
    if(season==="all")return [...TEAMS].sort((a,b)=>b.pts-a.pts).map(t=>({name:t.name,main:fmt(t.pts),label:"PTS",sub:"All Time"}));
    const idx=SEASONS.indexOf(season);
    return [...TEAMS].filter(t=>t.seasons[idx]>0).sort((a,b)=>b.seasons[idx]-a.seasons[idx]).map(t=>({name:t.name,main:fmt(t.seasons[idx]),label:"PTS",sub:SN[season],seasonName:historicalSeasonName(t.name,season)}));
  }
  const aLblMap={championship:"Championships",clarence:"Clarence Campbell Trophy",wales:"Prince of Wales Trophy",hart:"Hart Memorial Trophy",artross:"Art Ross Trophy",vezina:"The Vezina Trophy",mvfp:"The MVFP Trophy",calder:"The Calder Memorial Trophy"};
  return Object.keys(AWARDS).map(n=>({name:n,count:(AWARDS[n]?.[aMode]||[]).length,main:(AWARDS[n]?.[aMode]||[]).length,label:"WINS",sub:aLblMap[aMode]||aMode})).sort((a,b)=>b.count-a.count);
}


function historicalSeasonName(teamName,year){
  const historical=SEASON_NAMES?.[teamName]?.[String(year)];
  if(!historical || historical===teamName) return "";
  return historical;
}


const ROW_AWARD_ORDER=["championship","wales","clarence","hart","artross","vezina","calder","mvfp"];

function rowAwardsForTeam(name){
  const ta=AWARDS[name]||{};

  // Awards view name bar:
  // show ONLY the award selected by the current Awards tab.
  // Trophy case/dropdown remains unchanged.
  if(view==="awards"){
    return (ta[aMode]||[]).map(w=>({key:aMode,player:w.player||"",year:w.year||w.season||""}));
  }
  const selectedYear=(view==="rankings" && season!=="all" && !rMode) ? String(season) : null;

  // In individual season views, show ONLY awards won that season.
  // In all-time / records / awards views, show all-time championship count only, as before.
  if(selectedYear){
    const awards=[];
    ROW_AWARD_ORDER.forEach(key=>{
      (ta[key]||[]).forEach(w=>{
        if(String(w.year)===selectedYear){
          awards.push({key,player:w.player||"",year:w.year});
        }
      });
    });
    return awards;
  }

  return (ta.championship||[]).map(w=>({key:"championship",player:w.player||"",year:w.year}));
}

function rowAwardIconHtml(a){
  const labels={
    championship:"Championship",
    wales:"Prince of Wales Trophy",
    clarence:"Clarence Campbell Trophy",
    hart:"Hart",
    artross:"Art Ross",
    vezina:"Vezina",
    calder:"Calder Trophy",
    mvfp:"The MVFP Trophy"
  };
  const shortLabels={
    championship:"CUP",
    wales:"WALES",
    clarence:"CLARENCE",
    hart:"HART",
    artross:"ROSS",
    vezina:"VEZINA",
    calder:"ROOKIE",
    mvfp:"MFP"
  };
  const img=trophyImg(a.key,"row");
  const title=`${labels[a.key]||a.key}${a.player?": "+a.player:""}`;
  return `<span class="row-award row-award-${a.key}" title="${title}" aria-label="${title}"><span class="row-award-img">${img}</span><span class="row-award-label">${shortLabels[a.key]||a.key}</span></span>`;
}

function buildRow(item,i){
  const name=item.name, rank=i+1, isOpen=openIdx===i;
  const rowAwards=rowAwardsForTeam(name);
  const cupsHtml=rowAwards.length?rowAwards.map(rowAwardIconHtml).join(""):`<span class="no-cup">—</span>`;
  const tagSrc=DOGTAGS[name]||"";
  return `
  <div>
    <div class="row${isOpen?" open":""}" onclick="tog(${i})">
      <div class="r-rank${rank===2?" s2":rank===3?" s3":""}">${rank}</div>
      <div class="r-tag"><img src="${tagSrc}" alt="${name}" loading="lazy"></div>
      <div class="r-info">
        <div class="r-sub">${item.sub}</div>
        ${item.seasonName?`<div class="r-season-name">Season Name: <span>${item.seasonName}</span></div>`:""}
      </div>
      <div class="r-cups">${cupsHtml}</div>
      <div class="r-pts"><div class="r-pts-val">${item.main}</div><div class="r-pts-lbl">${item.label}</div></div>
      <div class="r-chev">⌄</div>
    </div>
    <div class="drop${isOpen?" open":""}">${isOpen?buildDrop(name):""}</div>
  </div>`;
}


function buildBestSeasonRow(item,i){
  const tagSrc=DOGTAGS[item.franchise]||"";
  const pct=(Number(item.pct)/100).toFixed(3).replace(/^0/,".");
  const fp=fmt(item.fpts);
  const hasHistoricalName=item.team && item.team!==item.franchise;
  const seasonNameNote=hasHistoricalName ? `${item.season} · Season Name: ${item.team}` : `${item.season}`;
  const mainA=bsMode==="points"?fp:item.record;
  const lblA=bsMode==="points"?"Fantasy Pts":"W-L-T";
  const mainB=bsMode==="points"?item.record:pct;
  const lblB=bsMode==="points"?"W-L-T":"Win %";
  const drawer=bestRosterOpen===i?buildRosterDrawer(item.franchise,i):"";
  return `<div class="best-season-shell">
  <div class="row best-season-row" onclick="toggleBestRoster(${i},'${String(item.franchise).replace(/'/g,"\\'")}')">
    <div class="r-rank${i===1?" s2":i===2?" s3":""}">${i+1}</div>
    <div class="r-tag"><img src="${tagSrc}" alt="${item.franchise}" loading="lazy"></div>
    <div class="bs-info">
      <div class="bs-sub">${seasonNameNote}</div><div class="api-roster-note" style="text-align:left;margin:6px 0 0">Current Fantrax roster only</div>
    </div>
    <div class="bs-stat"><div class="bs-stat-val">${mainA}</div><div class="bs-stat-lbl">${lblA}</div></div>
    <div class="bs-stat"><div class="bs-stat-val">${mainB}</div><div class="bs-stat-lbl">${lblB}</div></div>
    <div class="r-pts"><div class="r-pts-val">${bsMode==="points"?pct:fp}</div><div class="r-pts-lbl">${bsMode==="points"?"Win %":"FPts"}</div></div>
  </div>${drawer}</div>`;
}

function buildRulesPage(){
  return `<div class="ruleboard">
    <section class="rulebook-hero" aria-label="Forever Pool rules">
      <div class="rulebook-content">
        <div class="rulebook-kicker">Forever Pool</div>
        <h2 class="rulebook-title">Rule Board</h2>
        <div class="rule-card">
          <h3>Contract Rules</h3>
          <div class="rule-list">
            <div class="rule-item"><strong>Drafted Players:</strong> Drafted players receive 3 year contracts.</div>
            <div class="rule-item"><strong>Active Contracts:</strong> Any player with a contract is kept on the roster until the contract expires.</div>
          </div>
        </div>
        <div class="rule-card">
          <h3>RFA Contract</h3>
          <div class="rule-list">
            <div class="rule-item"><strong>Rule A:</strong> Is my player currently on an ELC, or was the last season they played part of the ELC? If no, they do not apply. If yes, continue to Rule B.</div>
            <div class="rule-item"><strong>Rule B:</strong> Is their contract in the pool expiring? If the answer to Rule A and Rule B is yes, then at the end of the year you can keep this player as an RFA Contract.</div>
            <div class="rule-item"><strong>Draft Pick Cost:</strong> Keeping a player as an RFA Contract uses a draft pick.</div>
            <div class="rule-item"><strong>Contract Extension:</strong> Because you are using a pick, this adds 3 years to their contract.</div>
          </div>
        </div>
        <div class="rule-note">More rules can be added here as the Forever Pool rulebook grows.</div>
      </div>
    </section>
  </div>`;
}


function awardWinnersByYear(key){
  const out={};
  Object.keys(AWARDS).forEach(team=>{
    (AWARDS[team]?.[key]||[]).forEach(w=>{
      const y=String(w.year);
      if(!out[y]) out[y]=[];
      out[y].push({team, year:y, player:w.player||""});
    });
  });
  return out;
}

function buildAwardPegBoard(key){
  const winners=awardWinnersByYear(key);
  const start=2020;
  const years=Array.from({length:24},(_,i)=>String(start+i));
  const title=aLbl(key);
  const posterSrc=AWARD_POSTERS[key]||"";
  const poster=posterSrc
    ? `<img src="${posterSrc}" alt="${title}" loading="lazy" onerror="this.style.display='none';this.nextElementSibling.style.display='block';"><div class="award-poster-fallback">${title}</div>`
    : `<div class="award-poster-fallback" style="display:block">${title}</div>`;
  const pegs=years.map(y=>{
    const seasonLabel=SN[y] || `${String(y).slice(-2)}/${String(Number(y)+1).slice(-2)}`;
    const wins=winners[y]||[];
    if(wins.length){
      return wins.map(w=>{
        const tagSrc=DOGTAGS[w.team]||"";
        return `<div class="peg-slot won">
          <div class="peg-year">${seasonLabel}</div>
          <div class="peg-notch" aria-hidden="true"></div>
          <div class="peg-dogtag"><img src="${tagSrc}" alt="${w.team}" loading="lazy"></div>
          <div class="peg-winner-name">${w.team}${w.player?`<span class="award-player-name">${w.player}</span>`:""}</div>
        </div>`;
      }).join("");
    }
    return `<div class="peg-slot empty">
      <div class="peg-year">${seasonLabel}</div>
      <div class="peg-notch" aria-hidden="true"></div>
      <div class="peg-empty">Open Peg</div>
    </div>`;
  }).join("");
  return `<div class="award-peg-page">
    <section class="award-peg-hero" aria-label="${title} winners tag frame">
      <div class="award-peg-content">
        <div class="award-peg-trophy">${poster}</div>
        <div class="peg-board">
          <div class="peg-grid">${pegs}</div>
        </div>
        <div class="trial-note">${title} winners wall</div>
      </div>
    </section>
  </div>`;
}

function tog(i){openIdx=openIdx===i?null:i;render();if(openIdx!==null){setTimeout(()=>{const rows=document.querySelectorAll(".row");if(rows[i])rows[i].scrollIntoView({behavior:"smooth",block:"start"});},60);}}
window.tog=tog;


