        try{
          const payload=await _api(ep);
          const found=_collectPotentialTrades(payload.data,ep);
          attempts.push({endpoint:ep,ok:true,found:found.length,shape:Array.isArray(payload.data)?`array(${payload.data.length})`:typeof payload.data});
          all.push(...found);
        }catch(e){attempts.push({endpoint:ep,ok:false,error:e.message||String(e)});}
