  function seasons(){let arr=[]; try{arr=getSeasonList();}catch(e){} return [`<option value="all">All Time</option>`].concat(arr.map(s=>`<option value="${esc(s)}">${esc((SN&&SN[s])||s)}</option>`)).join("");}
  window.buildTradeHistoryPage = buildTradeHistoryPage = function(){return `<div class="trade-history-page"><div class="trade-title">Matchup History</div><div class="trade-note">Select two teams to see head-to-head matchups returned by Fantrax League Info. Use All Time for every matchup the API exposes, or filter by season.</div><div class="trade-controls"><div class="trade-control"><label>Team One</label><select id="tradeTeamA" class="trade-select">${teamOptions()}</select></div><div class="trade-control"><label>Team Two</label><select id="tradeTeamB" class="trade-select">${teamOptions()}</select></div><div class="trade-control trade-season-row"><label class="trade-season-label">Season</label><select id="tradeSeason" class="trade-select">${seasons()}</select></div><button class="trade-button" onclick="runTradeSearch()">Find Matchups</button></div><div id="tradeResults" class="trade-results"><div class="trade-status">Choose two teams, then click Find Matchups.</div></div></div>`;};
  function refMatches(ref,keys){const rKeys=[ref?.id,ref?.teamId,ref?.name,ref?.teamName,ref?.fantasyTeamName].map(norm).filter(Boolean); return rKeys.some(k=>keys.includes(k)) || keys.some(k=>rKeys.some(r=>r.includes(k)||k.includes(r)));}
