    try{(await standings()).forEach(r=>{const rn=clean(r.teamName||r.name||''); if(norm(rn)===norm(name)||norm(rn).includes(norm(name))||norm(name).includes(norm(rn))){keys.push(rn,r.teamId,r.id);}})}catch(e){}
