    function walk(x,depth=0){ if(!x||typeof x!=='object'||depth>3)return; if(Array.isArray(x)){x.forEach(y=>walk(y,depth+1));return;} for(const [k,v] of Object.entries(x)){const nk=norm(k); if(/(score|fantasypoints|totalpoints|pointsfor|pointstotal|pts|pf)$/.test(nk)||/(score|fantasypoints|totalpointsfor|pointsfor)/.test(nk)){const n=nval(v); if(n!==null) priority.push({k,n});} if(v&&typeof v==='object')walk(v,depth+1);} }
