  function buildTeamComparePageV17(){const opts=(TEAMS||[]).map(t=>`<option value="${h(t.name)}">${h(t.name)}</option>`).join(''); const sopts=['<option value="all">All Time</option>'].concat(isBBL?['<option value="modern">Modern Era</option>']:[]).concat(seasonKeys().map(s=>`<option value="${h(s)}">${h(seasonLabel(s))}</option>`)).join(''); return `<div class="api-tool-page"><div class="api-tool-title">Team Compare</div><div class="api-tool-note">Compare two franchises by all-time totals${isBBL?', Modern Era totals':''}, any individual season, and trophy case history.</div><div class="api-controls"><div><label>Team One</label><select class="api-select" id="compareA">${opts}</select></div><div><label>Team Two</label><select class="api-select" id="compareB">${opts}</select></div><div><label>Scope</label><select class="api-select" id="compareScope">${sopts}</select></div><button class="api-button" onclick="runTeamCompare()">Compare Teams</button></div><div id="teamCompareOut"><div class="trade-status">Choose two teams, pick All Time${isBBL?', Modern Era':''} or a season, then click Compare Teams.</div></div></div>`;}
  window.runTeamCompare=function(){const out=document.getElementById('teamCompareOut'); if(!out)return; const a=teamByName(document.getElementById('compareA')?.value), b=teamByName(document.getElementById('compareB')?.value), scope=document.getElementById('compareScope')?.value||'all'; if(!a||!b){out.innerHTML='<div class="trade-status">Team not found.</div>';return;} const label=scope==='all'?'All-Time Franchise Comparison':scope==='modern'?'Modern Era Comparison — Since 2019':'Season Comparison: '+h(seasonLabel(scope)); out.innerHTML=`<div class="v16-scope-note">${label}</div><div class="api-compare-grid">${compareCard(a,scope)}${compareCard(b,scope)}</div><div class="v16-compare-divider"></div><div class="api-tool-note">${scope==='modern'?'Modern Era season-by-season points and records':'Season-by-season points and records'}</div>${seasonBreakdown(a,b,scope)}`;};
