(function(){
  function forceTickerFourCopies(){
    const el=document.getElementById('sportsCrawlTrack');
    if(!el || el.dataset.v20Done==='1') return;
    const html=el.innerHTML.trim();
    if(!html) return;
    // Earlier versions used 2-3 copies and animated the full track, which could create a blank gap on mobile.
    // V20 uses four identical copies and scrolls exactly one quarter of the track for a continuous sports ticker.
    el.innerHTML=html+html+html+html;
    el.dataset.v20Done='1';
  }
  const prevUpdate=window.updateTickerV18||window.updateTickerV17||window.updateTickerV16||window.loadTicker;
  window.updateTickerV20=async function(){
    if(typeof prevUpdate==='function'){
      await prevUpdate();
      const el=document.getElementById('sportsCrawlTrack');
      if(el){ el.dataset.v20Done='0'; }
    }
    setTimeout(forceTickerFourCopies,80);
  };
  const prevEnsure=window.ensureTabs;
  window.ensureTabs=function(){
    if(typeof prevEnsure==='function') prevEnsure();
    setTimeout(window.updateTickerV20,160);
  };
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',()=>setTimeout(window.updateTickerV20,350));
  else setTimeout(window.updateTickerV20,350);
})();

