  window.addEventListener('resize',()=>setTimeout(window.updateTickerV22,250),{passive:true});
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',()=>setTimeout(window.updateTickerV22,900));
  else setTimeout(window.updateTickerV22,900);
