(function(){
  function v29Esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}
  function v29Num(n){const x=Number(n);return Number.isFinite(x)?x.toLocaleString(undefined,{maximumFractionDigits:2}):'—';}
  function v29Ordinal(n){n=Number(n)||0;const s=['th','st','nd','rd'],v=n%100;return n+(s[(v-20)%10]||s[v]||s[0]);}
  function v29TeamOptions(){return (TEAMS||[]).map(t=>`<option value="${v29Esc(t.name)}">${v29Esc(t.name)}</option>`).join('');}

  function v29NormName(v){return String(v??'').toLowerCase().replace(/&amp;/g,'and').replace(/['’`]/g,'').replace(/[^a-z0-9]+/g,'').trim();}
  function v29AllTeams(){try{return Array.isArray(TEAMS)?TEAMS:[]}catch(e){return []}}
  function v29TeamByName(n){
    const wanted=v29NormName(n); if(!wanted)return null;
    const teams=v29AllTeams();
    for(const t of teams){
      const names=[t.name,t.id,t.teamId,t.fantraxTeamId,...(t.history||[]),...Object.values(t.seasonNames||{})].filter(Boolean);
      if(names.some(x=>v29NormName(x)===wanted))return t;
    }
    for(const t of teams){
      const names=[t.name,...(t.history||[]),...Object.values(t.seasonNames||{})].filter(Boolean).map(v29NormName);
      if(names.some(x=>x&&wanted&& (x.includes(wanted)||wanted.includes(x))))return t;
    }
    return null;
  }
  function v29ScopeOptions(data){let out=['<option value="all">All Time</option>']; if((typeof isBBL!=='undefined'&&isBBL)||((typeof FANTRAX_LIVE!=='undefined')&&FANTRAX_LIVE.league==='bbl'))out.push('<option value="modern">Modern Era</option>'); (data?.seasons||[]).slice().sort((a,b)=>Number(b.key)-Number(a.key)).forEach(s=>out.push(`<option value="${v29Esc(s.key)}">${v29Esc(s.label)}</option>`)); return out.join('');}
  function v29Dog(teamName){try{const t=v29TeamByName(teamName)||mhTeamByName(teamName)||{name:teamName}; const src=(typeof dogtagSrc==='function'?dogtagSrc(t):'') || t.dogtag || ((typeof DOGTAGS!=='undefined'&&DOGTAGS[teamName])?DOGTAGS[teamName]:''); return src?`<img src="${v29Esc(src)}" alt="${v29Esc(teamName)} dog tag" loading="lazy">`:`<div class="v29-team-name">${v29Esc(teamName)}</div>`;}catch(e){return `<div class="v29-team-name">${v29Esc(teamName)}</div>`;}}
  function v29RecHtml(rec){try{return typeof recText==='function'?recText(rec):`${rec?.w||0}-${rec?.l||0}-${rec?.t||0}`;}catch(e){return '—';}}
  function v29PctHtml(rec){try{return typeof pctText==='function'?pctText(rec):'—';}catch(e){return '—';}}
  function v29ScopeStatsSafe(name,scope){const t=v29TeamByName(name); if(!t)return {pts:0,rec:{w:0,l:0,t:0},rank:'—',label:scope}; try{return scopeStats(t,scope);}catch(e){return {pts:0,rec:{w:0,l:0,t:0},rank:'—',label:scope};}}
  function v29ValClass(a,b){a=Number(String(a).replace(/[^0-9.-]/g,'')); b=Number(String(b).replace(/[^0-9.-]/g,'')); if(!Number.isFinite(a)||!Number.isFinite(b)||a===b)return 'v29-even'; return a>b?'v29-winner':'v29-loser';}
  function v29Row(left,label,right,compare){let lc='',rc=''; if(compare){const l=Number(String(left).replace(/[^0-9.-]/g,'')), r=Number(String(right).replace(/[^0-9.-]/g,'')); if(Number.isFinite(l)&&Number.isFinite(r)&&l!==r){lc=l>r?'v29-winner':'v29-loser'; rc=r>l?'v29-winner':'v29-loser';} else {lc=rc='v29-even';}} return `<div class="v29-stat-row"><div class="v29-stat-val ${lc}">${v29Esc(left)}</div><div class="v29-stat-label">${v29Esc(label)}</div><div class="v29-stat-val ${rc}">${v29Esc(right)}</div></div>`;}
  function v29SeasonBreakdown(a,b,scope){try{return seasonBreakdown(v29TeamByName(a),v29TeamByName(b),scope);}catch(e){return ''}}

  function v33Hash(str){let h=0; for(const ch of String(str||'')){h=((h<<5)-h)+ch.charCodeAt(0); h|=0;} return Math.abs(h);}
  function v33PlayerName(teamName){const first=['Ace','Bobby','Johnny','Mickey','Rocky','Rusty','Gordie','Vinny','Marty','Danny','Tommy','Eddie','Reggie','Frankie','Charlie','Nicky']; const last=['Blades','Crossbar','Buckets','Stacks','Dangles','Slapper','Puckett','Ironwood','Top Shelf','Blue Line','Barnburner','Cherry','Five Hole','Chirps']; const h=v33Hash(teamName); return `${first[h%first.length]} ${last[(h>>4)%last.length]}`;}
  function v33Initials(teamName){return String(teamName||'').split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()||'FP';}
  function v34Palette(teamName){const h=v33Hash(teamName); const pals=[['#233d8c','#10182d'],['#9b1b24','#241015'],['#0f6a52','#082d25'],['#5f2b84','#1d102b'],['#d19125','#45270b'],['#1f4f6f','#101d29'],['#111111','#444444'],['#c75b12','#381b08'],['#285f99','#0d253d'],['#6b7b25','#252b0e']]; return pals[h%pals.length];}
  function v34Skin(teamName){return ['#e8c4a1','#c8906d','#f0d0ad','#8b5e46','#d6a27d'][v33Hash(teamName)%5];}
  function v34Hair(teamName){return ['#2d1c12','#5b351e','#111','#c29550','#6e4b2a'][(v33Hash(teamName)>>3)%5];}
  function v34StatRows(stats){const rows=[['GP',stats.gp],['W-L-T',`${stats.w}-${stats.l}-${stats.t}`],['FPts For',v29Num(stats.pf)],['FPts Against',v29Num(stats.pa)],['Avg For',v29Num(stats.avg)],['Point Edge',v29Num(stats.edge)],['Best Win Streak',stats.streak||0],['Current Streak',stats.current||'—']]; return rows.map(r=>`<tr><td>${v29Esc(r[0])}</td><td>${v29Esc(r[1])}</td></tr>`).join('');}
  function v29StreakText(streakObj){
    if(!streakObj || !streakObj.currentType || !streakObj.currentCount) return '—';
    return `${streakObj.currentType}${streakObj.currentCount}`;
  }
  function v34TeamStats(teamName,m,side){if(side==='a')return {gp:m.gp,w:m.w,l:m.l,t:m.t,pf:m.pf,pa:m.pa,avg:m.avgFor,edge:m.diff,streak:(m.streaks&&m.streaks[teamName]?m.streaks[teamName].bestWin:0),current:v29StreakText(m.streaks&&m.streaks[teamName])}; return {gp:m.gp,w:m.l,l:m.w,t:m.t,pf:m.pa,pa:m.pf,avg:m.avgAgainst,edge:-m.diff,streak:(m.streaks&&m.streaks[teamName]?m.streaks[teamName].bestWin:0),current:v29StreakText(m.streaks&&m.streaks[teamName])};}
  function v35PoolTitle(){try{return (typeof FANTRAX_LIVE!=='undefined'&&FANTRAX_LIVE.league==='bbl')?'Basement Bar League':'Forever Pool'}catch(e){return 'Fantrax Pool'}}
  function v35AwardLabels(){return {championship:'League Championships',presidents:'Presidents Trophies',clarence:'Clarence Campbell',wales:'Prince of Wales',hart:'Hart Trophies',norris:'Norris Trophies',vezina:'Vezina Trophies',calder:'Calder Trophies',artross:'Art Ross Trophies',mvfp:'MVFP Awards'};}
  function v35AwardKeys(){return ['championship','presidents','clarence','wales','hart','norris','vezina','calder','artross','mvfp'];}
  function v35TrophySrc(key){const map={championship:'championship.png',presidents:'presidents.png',clarence:'clarence.png',wales:'wales.png',hart:'hart.png',norris:'norris.png',vezina:'vezina.png',calder:'calder.png',artross:'artross.png',mvfp:'mvfp.png'};return `assets/trophies/${map[key]||'championship.png'}`;}
  function v35AwardList(teamName){const labels=v35AwardLabels(); const aw=(typeof AWARDS!=='undefined'&&AWARDS[teamName])?AWARDS[teamName]:{}; const rows=[]; v35AwardKeys().forEach(k=>{const arr=(aw&&Array.isArray(aw[k]))?aw[k]:[]; if(!arr.length)return; const years=arr.map(x=>String(x.year||x.season||'').trim()).filter(Boolean); const details=arr.map(x=>`${x.year||x.season||''}${x.player?' · '+x.player:''}`).filter(Boolean); rows.push({key:k,label:labels[k]||k,count:arr.length,years:years.join(', '),details:details.join(' / ')});}); return rows;}
  function v35AwardRows(teamName){const rows=v35AwardList(teamName); if(!rows.length)return `<div class="v35-empty-awards">No trophy case items listed yet.</div>`; return rows.slice(0,7).map(r=>`<div class="v35-award-row"><img src="${v29Esc(v35TrophySrc(r.key))}" alt="${v29Esc(r.label)}"><div class="v35-award-main"><div class="v35-award-name">${v29Esc(r.label)}</div><div class="v35-award-years">${v29Esc(r.details||r.years)}</div></div><div class="v35-award-count">${v29Esc(r.count)}</div></div>`).join('');}
  function v35TeamSummary(teamName){const st=v29ScopeStatsSafe(teamName,'all')||{}; const rec=st.rec||{w:0,l:0,t:0}; const awards=v35AwardList(teamName); const total=awards.reduce((s,a)=>s+a.count,0); const champ=(awards.find(a=>a.key==='championship')||{}).count||0; return `<div class="v35-franchise-summary-title">Franchise Summary</div><div class="v35-summary-grid"><span><b>Total Awards</b><b>${v29Esc(total)}</b></span><span><b>Championships</b><b>${v29Esc(champ)}</b></span><span><b>All-Time Record</b><b>${v29Esc(v29RecHtml(rec))}</b></span><span><b>Total FPts</b><b>${v29Esc(v29Num(st.pts||0))}</b></span></div>`;}
  function v35MatsFront(teamName){return v29NormName(teamName)==='matsyoursoupisready' && v35PoolTitle()==='Forever Pool' ? '<img class="v36-exact-card-img" src="assets/hockeycards/mats-your-soup-is-ready-front-exact.png" alt="Mats Your Soup is Ready hockey card front">' : '';}
  function v35MatsBack(teamName){return v29NormName(teamName)==='matsyoursoupisready' && v35PoolTitle()==='Forever Pool' ? '<img class="v36-exact-card-img" src="assets/hockeycards/mats-your-soup-is-ready-back-exact.png" alt="Mats Your Soup is Ready hockey card back trophy case">' : '';}
  function v33HockeyCard(teamName,opponent,scopeLabel,idx,stats){const initials=v33Initials(teamName); const num=(v33Hash(teamName)%91)+7; const pal=v34Palette(teamName); const skin=v34Skin(teamName); const hair=v34Hair(teamName); const pose=(v33Hash(teamName)%18-9)+'deg'; const pool=v35PoolTitle(); const staticFront=v35MatsFront(teamName); const staticBack=v35MatsBack(teamName); return `<div><div class="v33-hockey-card" role="button" tabindex="0" onclick="this.classList.toggle('flipped')" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();this.classList.toggle('flipped')}"><div class="v33-card-inner"><div class="v33-card-face v35-card-front ${staticFront?'v36-exact-card-face':''}" style="--c1:${pal[0]};--c2:${pal[1]};--skin:${skin};--hair:${hair};--pose:${pose}">${staticFront || `<div class="v35-pool-name">${v29Esc(pool)}</div><div class="v35-team-sash"><span>${v29Esc(teamName)}</span></div><div class="v35-photo-box"><div class="v35-rink"></div><div class="v35-crowd"></div><div class="v35-player"><div class="v35-stick"></div><div class="v35-arm left"></div><div class="v35-arm right"></div><div class="v35-leg left"></div><div class="v35-leg right"></div><div class="v35-skate left"></div><div class="v35-skate right"></div><div class="v35-torso" data-initials="${v29Esc(initials)}"></div><div class="v35-neck"></div><div class="v35-head"></div><div class="v35-helmet"></div><div class="v35-visor"></div><div class="v35-glove left"></div><div class="v35-glove right"></div></div><div class="v35-puck"></div></div><div class="v35-logo-circle">${v29Esc(initials)}</div><div class="v35-bottom-name">${v29Esc(teamName)}</div>`}</div><div class="v33-card-face v35-card-back ${staticBack?'v36-exact-card-face':''}">${staticBack || `<div class="v35-back-blue"></div><div class="v35-card-number">${num}</div><div class="v35-back-top-title">${v29Esc(teamName)}</div><div class="v35-pool-back">${v29Esc(pool)}</div><div class="v35-back-ribbon">Trophy Case</div><div class="v35-trophy-panel">${v35AwardRows(teamName)}</div><div class="v35-franchise-summary">${v35TeamSummary(teamName)}</div><div class="v35-card-footer">${v29Esc(pool)} All-Star</div><div class="v35-print-line">© O-Pee-Chee style · Printed in Canada</div>`}</div></div></div><div class="v33-card-hint">Click / tap card to flip</div></div>`;}
  function v29TrophyCards(a,b,scope,data){return '';}

  function v29MatchCard(data,a,b,scope){const games=mhPairGames(mhScopeGames(data.games||[],scope),a,b).sort((x,y)=>Number(x.seasonKey)-Number(y.seasonKey)||Number(x.period)-Number(y.period)); const m=mhSummarize(games,a,b); const stA=v29ScopeStatsSafe(a,scope), stB=v29ScopeStatsSafe(b,scope); const scopeLabel=scope==='all'?'All Time':scope==='modern'?'Modern Era':(data.seasons||[]).find(s=>String(s.key)===String(scope))?.label||scope; return `<div class="v29-scorecard"><div class="v29-card-title">Head-to-Head Comparison</div><div class="v29-card-sub"><span class="v29-mini-label">${v29Esc(scopeLabel)}</span> Static results database · Fantrax CSV history</div><div class="v29-matchup-layout"><div class="v29-team-side">${v29Dog(a)}<div class="v29-team-name">${v29Esc(a)}</div><div class="v29-team-record">${m.w}-${m.l}-${m.t}</div></div><div class="v29-stat-ladder">${v29Row(`${m.w}-${m.l}-${m.t}`,'H2H Record',`${m.l}-${m.w}-${m.t}`)}${v29Row(m.gp,'Games',m.gp)}${v29Row(v29Num(m.pf),'Total FPts',v29Num(m.pa),true)}${v29Row(v29Num(m.avgFor),'Avg FPts',v29Num(m.avgAgainst),true)}${v29Row(v29Num(m.diff),'Point Edge',v29Num(-m.diff),true)}${v29Row((m.streaks&&m.streaks[a]?m.streaks[a].bestWin:0),'Best Win Streak',(m.streaks&&m.streaks[b]?m.streaks[b].bestWin:0),true)}${v29Row(v29StreakText(m.streaks&&m.streaks[a]),'Current Streak',v29StreakText(m.streaks&&m.streaks[b]),true)}</div><div class="v29-team-side">${v29Dog(b)}<div class="v29-team-name">${v29Esc(b)}</div><div class="v29-team-record">${m.l}-${m.w}-${m.t}</div></div></div></div>`;}
  function v29RankBody(data,a,b,scope,view){const all=data.games||[]; const pair=mhPairGames(mhScopeGames(all,scope),a,b).sort((x,y)=>Number(x.seasonKey)-Number(y.seasonKey)||Number(x.period)-Number(y.period)); let title='Head-to-Head Game Log', body=mhGameTable(pair,a), note='Every saved matchup between the two selected teams.'; if(view==='season'){title='Season Breakdown'; body=mhSeasonBreakdown(pair,a,b); note='Head-to-head record split by season.';} if(view==='opponents'){title=`${a} vs Every Opponent`; body=mhOpponentRanks(all,scope,a); note='Ranks the selected team against every opponent in this scope.';} if(view==='rivalries'){title='League Rivalry Rankings'; body=mhRivalryRanks(all,scope); note='Ranks the busiest and closest rivalries across the league.';} if(view==='blowouts'){title='Biggest Blowouts'; body=mhSpecialGames(all,scope,'blowouts'); note='Largest margins in the selected scope.';} if(view==='closest'){title='Closest Games'; body=mhSpecialGames(all,scope,'closest'); note='Smallest margins in the selected scope.';} if(view==='highest'){title='Highest-Scoring Games'; body=mhSpecialGames(all,scope,'highest'); note='Highest combined fantasy point games.';} return `<div class="v29-section"><div class="v29-section-title">${v29Esc(title)}</div><div class="v29-rank-note">${v29Esc(note)}</div>${body}</div>`;}
  function buildTeamComparePageV29(){const views='<option value="games">Head-to-Head Game Log</option><option value="season">Season Breakdown</option><option value="opponents">Team One vs All Opponents</option><option value="rivalries">League Rivalry Rankings</option><option value="blowouts">Biggest Blowouts</option><option value="closest">Closest Games</option><option value="highest">Highest-Scoring Games</option>'; return `<div class="v29-page"><div class="v29-title">Team Comparison</div><div class="v29-note">Select two franchises to compare the full static matchup history built from your Fantrax Results CSV exports, then flip each hockey card to view the trophy case.</div><div class="v29-controls"><div><label>Team One</label><select class="v29-select" id="compareA">${v29TeamOptions()}</select></div><div><label>Team Two</label><select class="v29-select" id="compareB">${v29TeamOptions()}</select></div><div><label>Season / Era</label><select class="v29-select" id="compareScope"><option value="all">All Time</option><option value="loading">Loading seasons...</option></select></div><div><label>View / Ranking</label><select class="v29-select" id="compareView">${views}</select></div><div class="v29-action"><button class="v29-button" onclick="runTeamCompare()">Compare Teams</button></div></div><div id="teamCompareOut"><div class="v29-status">Loading matchup database...</div></div></div>`;}
  window.runTeamCompare=async function(){const out=document.getElementById('teamCompareOut'); if(!out)return; try{const data=await mhLoad(); const scopeSel=document.getElementById('compareScope'); if(scopeSel&&scopeSel.querySelector('option[value="loading"]'))scopeSel.innerHTML=v29ScopeOptions(data); const a=document.getElementById('compareA')?.value||mhTeams()[0]?.name; const b=document.getElementById('compareB')?.value||mhTeams()[1]?.name; const scope=document.getElementById('compareScope')?.value||'all'; const view=document.getElementById('compareView')?.value||'games'; if(!a||!b||a===b){out.innerHTML='<div class="v29-status">Choose two different teams.</div>';return;} out.innerHTML=v29MatchCard(data,a,b,scope)+`<div class="v29-section"><div class="v29-section-title">Hockey Card</div>${v29TrophyCards(a,b,scope,data)}</div>`+v29RankBody(data,a,b,scope,view); }catch(e){out.innerHTML=`<div class="v29-status">Team comparison failed: ${v29Esc(e.message||String(e))}</div>`;}};
  function removeMatchupsTabV29(){const tab=document.getElementById('tabMatchups'); if(tab)tab.remove(); const comp=document.getElementById('tabCompare'); if(comp)comp.textContent='Team Comparison';}
  const prevEnsureV29=window.ensureTabs; window.ensureTabs=function(){if(typeof prevEnsureV29==='function')prevEnsureV29(); removeMatchupsTabV29();};
  const prevRenderV29=window.render||render; window.render=render=function(){ if(view==='matchups')view='teamcompare'; if(view==='teamcompare'){document.getElementById('board').innerHTML=buildTeamComparePageV29(); mhLoad().then(data=>{const sel=document.getElementById('compareScope'); if(sel)sel.innerHTML=v29ScopeOptions(data); runTeamCompare();}).catch(e=>{const out=document.getElementById('teamCompareOut'); if(out)out.innerHTML=`<div class="v29-status">${v29Esc(e.message||String(e))}</div>`;}); return;} return prevRenderV29();};
  const prevCtrlV29=window.ctrl||ctrl; window.ctrl=ctrl=function(){prevCtrlV29(); removeMatchupsTabV29(); const comp=document.getElementById('tabCompare'); if(comp)comp.classList.toggle('active',view==='teamcompare'); if(view==='teamcompare'){['fRowEra','fRow1','fRow2','fRowA'].forEach(id=>{const el=document.getElementById(id); if(el)el.classList.add('hide');});}};
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',removeMatchupsTabV29); else removeMatchupsTabV29();
})();

