(function(){
  const v37CardMap = {
    "Cujo": "cujo",
    "Don": "don",
    "Dish": "dish",
    "Red Dragon": "red-dragon",
    "Mats Your Soup is Ready": "mats-your-soup-is-ready",
    "Blues Brothers": "blues-brothers",
    "NG United": "ng-united",
    "The Kings Cowboys": "the-kings-cowboys",
    "Damo": "damo",
    "No Regretzky": "no-regretzky",
    "North Kariya": "north-kariya",
    "Team Trash": "team-trash"
  };
  function v37TeamKey(teamName){
    if(v37CardMap[teamName]) return v37CardMap[teamName];
    const clean = String(teamName||'').toLowerCase().replace(/&/g,'and').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'');
    return clean;
  }
  window.v35MatsFront = function(teamName){
    if(typeof v35PoolTitle==='function' && v35PoolTitle()==='Forever Pool'){
      const key=v37TeamKey(teamName);
      return `<img class="v36-exact-card-img v37-static-card-img" src="assets/hockeycards/${key}-front.png" alt="${String(teamName||'Team').replace(/"/g,'&quot;')} hockey card front">`;
    }
    return '';
  };
  window.v35MatsBack = function(teamName){
    if(typeof v35PoolTitle==='function' && v35PoolTitle()==='Forever Pool'){
      const key=v37TeamKey(teamName);
      return `<img class="v36-exact-card-img v37-static-card-img" src="assets/hockeycards/${key}-back.png" alt="${String(teamName||'Team').replace(/"/g,'&quot;')} hockey card back">`;
    }
    return '';
  };
})();

