(function(){
  const V57_POOL_NAME = "Forever Pool";
  const V57_HAS_MODERN = false;
  const V57_STORE = 'poolUpdates:v57:' + V57_POOL_NAME.replace(/\s+/g,'-').toLowerCase();
  let v57Open=null;
  function esc(x){return String(x??'').replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s]));}
  function norm(x){return String(x||'').toLowerCase().replace(/&/g,'and').replace(/[^a-z0-9]+/g,'');}
  function n(x){const v=Number(x); return Number.isFinite(v)?v:0;}
  function fmt(x){try{if(typeof window.fmt==='function')return window.fmt(x);}catch(e){}return n(x).toLocaleString(undefined,{maximumFractionDigits:2});}
  function recText(r){return `${n(r&&r.w)}-${n(r&&r.l)}-${n(r&&r.t)}`;}
  function recPct(r){const w=n(r&&r.w),l=n(r&&r.l),t=n(r&&r.t),gp=w+l+t;return gp?((w+t*.5)/gp)*100:0;}
  function pctText(v){return n(v).toFixed(1)+'%';}
  function seasonLabel(s){try{if(typeof SN!=='undefined'&&SN&&SN[s])return SN[s];}catch(e){} return String(s||'');}
  function seasonSortValue(s){const m=String(s||'').match(/20\d{2}|\d{2}/); if(!m)return 0; const raw=Number(m[0]); return raw<100?2000+raw:raw;}
  function modernSeason(s){return seasonSortValue(s)>=2019;}
  function scopeSeasons(){
    try{if(V57_HAS_MODERN && era==='modern' && typeof MODERN!=='undefined')return Array.from(MODERN).map(String);}catch(e){}
    try{if(typeof SEASONS!=='undefined')return Array.from(SEASONS).map(String);}catch(e){}
    try{if(typeof SEASON_RECORDS!=='undefined')return Array.from(new Set(SEASON_RECORDS.map(r=>String(r.year||r.season))));}catch(e){}
    return [];
  }
  function awardSeasonVariants(v){const s=String(v||''); const out=new Set([s]); const m=s.match(/(20\d{2})/); if(m){const y=Number(m[1]); out.add(String(y)); out.add(`${y}/${String(y+1).slice(-2)}`); out.add(String(y).slice(-2)+'/'+String(y+1).slice(-2));} const m2=s.match(/^(\d{2})$/); if(m2){const y=2000+Number(m2[1]); out.add(String(y)); out.add(`${y}/${String(y+1).slice(-2)}`); out.add(String(y).slice(-2)+'/'+String(y+1).slice(-2));} return Array.from(out);}
  function teamsList(){try{return Array.isArray(TEAMS)?TEAMS:[];}catch(e){return [];}}
  function teamName(t){return t&&t.name?String(t.name):'';}
  function teamByName(name){return teamsList().find(t=>norm(teamName(t))===norm(name))||teamsList().find(t=>norm(teamName(t)).includes(norm(name))||norm(name).includes(norm(teamName(t))));}
  const FP_MANAGER_BY_TEAM = {
    // Forever Pool source file does not currently include per-season manager fields; these fall back to franchise names until true manager names are added.
  };
  function managerForTeamSeason(t,s){
    if(!t)return '';
    if(t.owners){const variants=awardSeasonVariants(s); for(const k of variants){if(t.owners[k])return String(t.owners[k]);}}
    return FP_MANAGER_BY_TEAM[teamName(t)] || teamName(t);
  }
  function rowPointsForTeamSeason(t,s){
    if(!t)return 0;
    if(t.seasons && !Array.isArray(t.seasons))return n(t.seasons[s]);
    if(Array.isArray(t.seasons)){try{const idx=Array.from(SEASONS).map(String).indexOf(String(s)); return idx>=0?n(t.seasons[idx]):0;}catch(e){return 0;}}
    return 0;
  }
  function rowRecordForTeamSeason(t,s){
    if(!t)return {w:0,l:0,t:0};
    if(t.records){const variants=awardSeasonVariants(s); for(const k of variants){if(t.records[k])return {w:n(t.records[k].w),l:n(t.records[k].l),t:n(t.records[k].t)};}}
    try{if(typeof summedRecordForTeam==='function')return summedRecordForTeam(teamName(t),'selected');}catch(e){}
    return {w:0,l:0,t:0};
  }
  function buildManagerRows(){
    if(V57_POOL_NAME==='Forever Pool')return buildForeverManagerRows();
    const seasons = season==='all' ? scopeSeasons() : [String(season)];
    const map = new Map();
    teamsList().forEach(t=>seasons.forEach(s=>{
      const pts=rowPointsForTeamSeason(t,s); if(!pts && season!=='all')return;
      const mgr=managerForTeamSeason(t,s)||'Unknown Manager';
      if(!map.has(mgr))map.set(mgr,{name:mgr,pts:0,w:0,l:0,t:0,seasons:new Set(),teams:new Set(),latestTeam:''});
      const o=map.get(mgr), r=rowRecordForTeamSeason(t,s); o.pts+=pts;o.w+=n(r.w);o.l+=n(r.l);o.t+=n(r.t);o.seasons.add(s);o.teams.add(teamName(t)); if(!o.latestTeam||seasonSortValue(s)>=seasonSortValue(o.latestSeason)){o.latestTeam=teamName(t);o.latestSeason=s;}
    }));
    return Array.from(map.values()).map(o=>{o.raw = rMode==='record'||rMode==='winpct'?recPct(o):rMode==='plusminus'?(o.w-o.l):o.pts; o.main=rMode==='record'?recText(o):rMode==='winpct'?pctText(recPct(o)):rMode==='plusminus'?((o.w-o.l)>=0?'+':'')+(o.w-o.l):fmt(o.pts); o.label=rMode==='record'?'Record':rMode==='winpct'?'Win %':rMode==='plusminus'?'+/-':'PTS'; o.sub=(season==='all'?(era==='modern'?'Modern Era':'All Time'):seasonLabel(season))+' · Manager Ranking'; return o;}).sort((a,b)=>b.raw-a.raw || b.pts-a.pts || a.name.localeCompare(b.name));
  }
  function buildForeverManagerRows(){
    const rows=[];
    try{
      const source = (typeof SEASON_RECORDS!=='undefined'&&Array.isArray(SEASON_RECORDS)) ? SEASON_RECORDS : [];
      if(source.length){
        const wanted = season==='all' ? null : String(season);
        const map=new Map();
        source.forEach(r=>{const key=String(r.year||r.season); if(wanted && key!==wanted)return; const franchise=r.franchise||r.name||r.team; const mgr=FP_MANAGER_BY_TEAM[franchise]||franchise; if(!map.has(mgr))map.set(mgr,{name:mgr,pts:0,w:0,l:0,t:0,seasons:new Set(),teams:new Set(),latestTeam:franchise}); const o=map.get(mgr); o.pts+=n(r.fpts||r.points);o.w+=n(r.w);o.l+=n(r.l);o.t+=n(r.t);o.seasons.add(key);o.teams.add(franchise); if(seasonSortValue(key)>=seasonSortValue(o.latestSeason)){o.latestSeason=key;o.latestTeam=franchise;}});
        return Array.from(map.values()).map(o=>{o.raw=rMode==='record'||rMode==='winpct'?recPct(o):rMode==='plusminus'?(o.w-o.l):o.pts;o.main=rMode==='record'?recText(o):rMode==='winpct'?pctText(recPct(o)):rMode==='plusminus'?((o.w-o.l)>=0?'+':'')+(o.w-o.l):fmt(o.pts);o.label=rMode==='record'?'Record':rMode==='winpct'?'Win %':rMode==='plusminus'?'+/-':'PTS';o.sub=(season==='all'?'All Time':seasonLabel(season))+' · Manager Ranking';return o;}).sort((a,b)=>b.raw-a.raw||b.pts-a.pts||a.name.localeCompare(b.name));
      }
    }catch(e){}
    return teamsList().map(t=>{const name=FP_MANAGER_BY_TEAM[teamName(t)]||teamName(t); const pts=season==='all'?n(t.pts):rowPointsForTeamSeason(t,season); return {name,pts,w:0,l:0,t:0,teams:new Set([teamName(t)]),latestTeam:teamName(t),raw:pts,main:fmt(pts),label:'PTS',sub:(season==='all'?'All Time':seasonLabel(season))+' · Manager Ranking'};}).sort((a,b)=>b.raw-a.raw);
  }
  const awardLabels={championship:'Championships',presidents:'Presidents Trophy',clarence:'Clarence Campbell',wales:'Prince of Wales',hart:'Hart',norris:'Norris',artross:'Art Ross',vezina:'Vezina',mvfp:'MVFP',calder:'Calder'};
  const awardKeys=['championship','presidents','clarence','wales','hart','norris','artross','vezina','mvfp','calder'];
  function managerAwards(manager){
    const out=[];
    try{Object.keys(AWARDS||{}).forEach(team=>{const t=teamByName(team)||{name:team}; const aw=AWARDS[team]||{}; awardKeys.forEach(k=>(aw[k]||[]).forEach(w=>{const sy=w.season||w.year||''; if(V57_HAS_MODERN && era==='modern' && !modernSeason(sy))return; const mgr=managerForTeamSeason(t,sy); if(norm(mgr)===norm(manager)){out.push({key:k,label:awardLabels[k]||k,season:sy,player:w.player||'',team:team});}}));});}catch(e){}
    return out.sort((a,b)=>seasonSortValue(b.season)-seasonSortValue(a.season));
  }
  function trophyHtmlForManager(manager){const arr=managerAwards(manager); if(!arr.length)return '<div class="v16-award-empty">No trophy case items listed.</div>'; return arr.map(a=>`<span class="v16-award-pill"><b>${esc(a.label)}</b>${a.season?` ${esc(a.season)}`:''}${a.player?` · ${esc(a.player)}`:''}${a.team?` · ${esc(a.team)}`:''}</span>`).join('');}
  function managerDrop(o){const pm=o.w-o.l; const rec=`<div class="rec-strip"><div class="rec-cell"><div class="rec-val">${o.w||0}</div><div class="rec-lbl">Wins</div></div><div class="rec-cell"><div class="rec-val">${o.l||0}</div><div class="rec-lbl">Losses</div></div><div class="rec-cell"><div class="rec-val">${o.t||0}</div><div class="rec-lbl">Ties</div></div><div class="rec-cell"><div class="rec-val">${pctText(recPct(o))}</div><div class="rec-lbl">Win %</div></div><div class="rec-cell"><div class="rec-val">${pm>=0?'+':''}${pm}</div><div class="rec-lbl">+/-</div></div></div>`; const teams=Array.from(o.teams||[]).filter(Boolean).join(' → '); return rec+`<div class="drop-section">Manager Trophy Case</div><div class="v16-trophy-list">${trophyHtmlForManager(o.name)}</div>${teams?`<div class="hist">Managed team history: ${esc(teams)}</div>`:''}`;}
  function buildManagerRankingsPage(){const rows=buildManagerRows(); if(!rows.length)return '<div class="v57-page"><div class="v57-title">Rank By Manager</div><div class="v57-empty">No manager ranking data found.</div></div>'; return rows.map((o,i)=>{const open=v57Open===i; return `<div><div class="row${open?' open':''}" onclick="window.v57ToggleManager(${i})"><div class="r-rank${i===1?' s2':i===2?' s3':''}">${i+1}</div><div class="r-tag"><div class="v57-manager-mark"><span class="v57-manager-name">${esc(o.name)}</span></div></div><div class="r-info"><div class="r-sub">${esc(o.sub)}</div>${o.latestTeam?`<div class="r-owner">Current / latest team: ${esc(o.latestTeam)}</div>`:''}</div><div class="r-cups">${managerAwards(o.name).filter(a=>a.key==='championship').length?managerAwards(o.name).filter(a=>a.key==='championship').map(a=>'<span class="row-award row-award-championship"><span class="row-award-label">CUP</span></span>').join(''):'<span class="no-cup">—</span>'}</div><div class="r-pts"><div class="r-pts-val">${esc(o.main)}</div><div class="r-pts-lbl">${esc(o.label)}</div></div><div class="r-chev">⌄</div></div><div class="drop${open?' open':''}">${open?managerDrop(o):''}</div></div>`;}).join('');}
  window.v57ToggleManager=function(i){v57Open=v57Open===i?null:i; render();};
  function loadUpdates(){try{return JSON.parse(localStorage.getItem(V57_STORE)||'[]');}catch(e){return [];}}
  function saveUpdates(q){localStorage.setItem(V57_STORE,JSON.stringify(q));}
  function defaultUpdates(){return loadUpdates();}
  function buildPoolUpdatesPage(){const q=defaultUpdates(); return `<div class="v57-page"><div class="v57-title">Pool Updates</div><div class="v57-note">Admin can add vote questions here. This first version enforces one vote per voter name in this browser storage and lets that voter change their vote. A server/database can make it truly cross-device later.</div><div class="v57-form"><input id="v57Voter" placeholder="Your manager name"><div class="v57-admin-row"><textarea id="v57Question" placeholder="Admin: type a new question"></textarea><button class="v57-button" onclick="v57AddQuestion()">Add Question</button></div><input id="v57Options" placeholder="Options separated by commas, ex: Yes, No, Maybe"></div><div id="v57Questions">${q.map(questionCard).join('')}</div></div>`;}
  function questionCard(q){const totals={}; (q.options||[]).forEach(o=>totals[o]=0); Object.values(q.votes||{}).forEach(v=>{if(totals[v]!=null)totals[v]++;}); const total=Object.values(totals).reduce((a,b)=>a+b,0); const opts=(q.options||[]).map(o=>{const count=totals[o]||0,p=total?Math.round(count/total*100):0; return `<label class="v57-option"><input type="radio" name="v57_${esc(q.id)}" value="${esc(o)}"><span>${esc(o)}</span><span class="v57-small">${count} vote${count===1?'':'s'} · ${p}%</span><span class="v57-bar"><span class="v57-fill" style="width:${p}%"></span></span></label>`;}).join(''); return `<article class="v57-question-card"><div class="v57-award-kicker">${esc(q.question)}</div><div class="v57-small">${total} total vote${total===1?'':'s'}</div>${opts}<button class="v57-button" onclick="v57SubmitVote('${esc(q.id)}')">Submit / Change Vote</button></article>`;}
  window.v57AddQuestion=function(){const qtxt=document.getElementById('v57Question')?.value.trim(); const opts=(document.getElementById('v57Options')?.value||'').split(',').map(x=>x.trim()).filter(Boolean); if(!qtxt||opts.length<2){alert('Add a question and at least two comma-separated options.');return;} const qs=loadUpdates(); qs.unshift({id:'q_'+Date.now(),question:qtxt,options:opts,votes:{}}); saveUpdates(qs); render();};
  window.v57SubmitVote=function(id){const voter=(document.getElementById('v57Voter')?.value||'').trim(); if(!voter){alert('Type your manager name first.');return;} const selected=document.querySelector(`input[name="v57_${CSS.escape(id)}"]:checked`); if(!selected){alert('Pick an option first.');return;} const qs=loadUpdates(); const q=qs.find(x=>x.id===id); if(!q)return; q.votes=q.votes||{}; q.votes[voter]=selected.value; saveUpdates(qs); render();};
  function addTabs(){const tabs=document.querySelector('.tabs'); if(!tabs)return; if(!document.getElementById('tabManagerRank')){const b=document.createElement('button'); b.className='tab'; b.id='tabManagerRank'; b.textContent='Rank By Manager'; b.onclick=()=>setView('managerrankings'); const after=document.getElementById('tabR'); after&&after.parentNode?after.parentNode.insertBefore(b,after.nextSibling):tabs.appendChild(b);} if(!document.getElementById('tabPoolUpdates')){const b=document.createElement('button'); b.className='tab'; b.id='tabPoolUpdates'; b.textContent='Pool Updates'; b.onclick=()=>setView('poolupdates'); tabs.appendChild(b);}}
  const oldRender=window.render||render; window.render=render=function(){ if(view==='managerrankings'){document.getElementById('board').innerHTML=buildManagerRankingsPage();return;} if(view==='poolupdates'){document.getElementById('board').innerHTML=buildPoolUpdatesPage();return;} return oldRender(); };
  const oldCtrl=window.ctrl||ctrl; window.ctrl=ctrl=function(){oldCtrl(); addTabs(); const mgr=document.getElementById('tabManagerRank'); if(mgr)mgr.classList.toggle('active',view==='managerrankings'); const upd=document.getElementById('tabPoolUpdates'); if(upd)upd.classList.toggle('active',view==='poolupdates'); if(view==='managerrankings'){const f1=document.getElementById('fRow1'),f2=document.getElementById('fRow2'),fa=document.getElementById('fRowA'),fe=document.getElementById('fRowEra'); if(f1)f1.classList.remove('hide'); if(f2)f2.classList.remove('hide'); if(fa)fa.classList.add('hide'); if(fe)fe.classList.toggle('hide',!V57_HAS_MODERN);} if(view==='poolupdates'){['fRowEra','fRow1','fRow2','fRowA'].forEach(id=>{const el=document.getElementById(id); if(el)el.classList.add('hide');});}};
  const oldSetView=window.setView||setView; window.setView=function(v){ if(v==='nhlawards')v='awards'; if(['managerrankings','poolupdates'].includes(v)){view=v;openIdx=null;v57Open=null;rMode=null;season='all';ctrl();render();return;} oldSetView(v);};
  const oldEnsure=window.ensureTabs; window.ensureTabs=function(){if(typeof oldEnsure==='function')oldEnsure(); addTabs();};
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>{addTabs();}); else {addTabs();} setTimeout(()=>{try{ctrl();}catch(e){}},600);
})();

