  function norm(x){return String(x||'').toLowerCase().replace(/&/g,'and').replace(/[^a-z0-9]+/g,'');}
  function poolName(){try{return typeof V57_POOL_NAME!=='undefined'?V57_POOL_NAME:(document.title||'Pool');}catch(e){return document.title||'Pool';}}
  function poolSlug(){const p=poolName(); return /forever/i.test(p)?'forever':'bbl';}

  const V70_STYLE_OPTIONS=[['chalkboard','Neon Chalkboard'],['trophy','Trophy Plaque'],['dogtags','Dog Tag Wall'],['card','Hockey Card'],['jumbotron','Jumbotron'],['coaster','Beer Coaster'],['locker','Locker Room'],['folder','Draft Folder'],['brick','Graffiti Brick'],['ticket','Ticket Stub']];
  function v70StyleKey(){return 'poolUpdates:v70:cardStyle:'+poolSlug();}
