(function(){
  const YEAR='2025';
  const DISPLAY_SEASON='2025-26 / 2026 Awards';
  const TEAM_AWARDS=[
    {group:'Team Awards', award:'Pool Champ', team:'Blues Brothers', prize:'$570.05'},
    {group:'Conference Winners', award:'Clarence Campbell', team:"Damo's Dusters", prize:'$100'},
    {group:'Conference Winners', award:'Prince of Wales', team:"Don's Cherry Pickers", prize:'$100'}
  ];
  const PLAYER_AWARDS=[
    {group:'Player Awards', award:'Hart', player:'Nikita Kucherov', team:"Damo's Dusters", prize:'$75'},
    {group:'Player Awards', award:'Vezina', player:'Andrei Vasilevskiy', team:"Don's Cherry Pickers", prize:'$50'},
    {group:'Player Awards', award:'Calder', player:'Matthew Schaefer', team:'NG United', prize:'$25'},
    {group:'Player Awards', award:'Norris', player:'Zach Werenski', team:'The Kings Cowboys', displayTeam:'Queens Cowboys', prize:'$50'},
    {group:'Player Awards', award:'Rocket Richard', player:'Nathan MacKinnon', team:"Damo's Dusters", prize:'$50'},
    {group:'Player Awards', award:'Most Fantasy Pts', player:'Connor McDavid', team:'Blues Brothers', prize:'$50'}
  ];
  const ALL_AWARDS=[...TEAM_AWARDS,...PLAYER_AWARDS];
  function esc(x){return String(x??'').replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s]));}
  function norm(x){return String(x||'').toLowerCase().replace(/&/g,'and').replace(/[^a-z0-9]+/g,'');}
  function teamLookup(name){
    const aliases={dcp:"Don's Cherry Pickers",queenscowboys:'The Kings Cowboys',thequeenscowboys:'The Kings Cowboys'};
    const wanted=aliases[norm(name)]||name;
    try{if(typeof teamByName==='function'){const t=teamByName(wanted); if(t)return t;}}catch(e){}
    try{if(Array.isArray(TEAMS)){return TEAMS.find(t=>norm(t.name)===norm(wanted))||TEAMS.find(t=>norm(t.name).includes(norm(wanted))||norm(wanted).includes(norm(t.name)));}}catch(e){}
    return {name:wanted};
  }
  function dogSrc(teamName){
    const t=teamLookup(teamName)||{name:teamName};
    const nm=t.name||teamName;
    try{if(typeof dogtagSrc==='function'){const s=dogtagSrc(t); if(s)return s;}}catch(e){}
    try{if(typeof DOGTAGS!=='undefined'&&DOGTAGS&&DOGTAGS[nm])return DOGTAGS[nm];}catch(e){}
    try{if(t&&t.dogtag)return t.dogtag;}catch(e){}
    return '';
  }
  function teamChip(a){
    const src=dogSrc(a.team);
    const label=a.displayTeam||a.team;
    return `<div class="v61-team-chip">${src?`<img src="${esc(src)}" alt="${esc(label)} dog tag" loading="lazy">`:''}<span>${esc(label)}</span></div>`;
  }
  function card(a){
    const isPlayer=!!a.player;
    return `<article class="v61-award-card"><div class="v61-award-kicker">${esc(a.group)}</div><div class="v61-award-name">${esc(a.award)}</div>${isPlayer?`<div class="v61-award-player">${esc(a.player)}</div>`:''}<div class="v61-award-money">${esc(a.prize)}</div>${teamChip(a)}</article>`;
  }
  function buildForeverAwardsPage(){
    return `<div class="v61-awards-page"><div class="v61-awards-title">Forever Pool Awards</div><div class="v61-awards-note">Updated from the commissioner-provided 2026 Forever Pool award list. Last year’s placeholder team names are ignored.</div><div class="v61-awards-section-title">Team Awards</div><div class="v61-awards-grid">${TEAM_AWARDS.map(card).join('')}</div><div class="v61-awards-section-title">Player Awards</div><div class="v61-awards-grid">${PLAYER_AWARDS.map(card).join('')}</div><div class="v61-finance"><div>Prize Total<b>$1,070.05</b></div><div>Buy-In<b>$100 × 12 = $1,200.00</b></div><div>Pool Cost<b>$129.95</b></div><div>Per Person Cost<b>$10.82</b></div></div></div>`;
  }
  function applyForeverAwardsToData(){
    try{if(typeof TROPHY_IMGS!=='undefined'&&TROPHY_IMGS&&!TROPHY_IMGS.norris)TROPHY_IMGS.norris='assets/trophies/norris.png';}catch(e){}
    try{
      if(typeof AWARDS==='undefined'||!AWARDS)return;
      const keys=['championship','clarence','wales','hart','vezina','calder','norris','mvfp','artross'];
      Object.keys(AWARDS).forEach(team=>{keys.forEach(k=>{if(Array.isArray(AWARDS[team][k]))AWARDS[team][k]=AWARDS[team][k].filter(x=>String(x.year)!==YEAR);});});
      function add(team,key,player){if(!AWARDS[team])AWARDS[team]={}; if(!Array.isArray(AWARDS[team][key]))AWARDS[team][key]=[]; AWARDS[team][key].push(player?{year:YEAR,player}:{year:YEAR});}
      add('Blues Brothers','championship');
      add("Damo's Dusters",'clarence');
      add("Don's Cherry Pickers",'wales');
      add("Damo's Dusters",'hart','Kucherov');
      add("Don's Cherry Pickers",'vezina','Vasilevskiy');
      add('NG United','calder','Schaefer');
      add('The Kings Cowboys','norris','Werenski');
      add('Blues Brothers','mvfp','McDavid');
      // Rocket Richard has no historical trophy key in the original Forever Pool trophy grid, so it is shown on the new Awards page/ticker only.
    }catch(e){}
  }
  applyForeverAwardsToData();
  const oldRender=window.render;
  window.render=function(){
    try{if(typeof view!=='undefined'&&view==='awards'){const board=document.getElementById('board'); if(board){board.innerHTML=buildForeverAwardsPage(); return;}}}catch(e){}
    return oldRender&&oldRender.apply(this,arguments);
  };
  function boot(){applyForeverAwardsToData(); try{if(typeof view!=='undefined'&&view==='awards')render();}catch(e){}}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot); else boot();
})();

