(function(){
  function awardEndYear(v, short){
    const s=String(v||'').trim();
    if(!s)return '';
    const range=s.match(/^(\d{4})\s*\/\s*(\d{2,4})$/);
    if(range){
      const start=Number(range[1]);
      const tail=range[2];
      const end=tail.length===4?Number(tail):(Math.floor(start/100)*100+Number(tail));
      return short?String(end).slice(-2):String(end);
    }
    if(/^\d{4}$/.test(s)){
      const end=Number(s)+1;
      return short?String(end).slice(-2):String(end);
    }
    return s;
  }
  window.awardEndYear=awardEndYear;
  try{
    trophyItems=function(wins,key,size=''){
      if(!wins||!wins.length)return `<span class="tr-none">None</span>`;
      return wins.slice().sort((a,b)=>String(a.year||a.season||'').localeCompare(String(b.year||b.season||''))).map(w=>{
        const raw=w.year||w.season||'';
        return `<div class="tr">${trophyImg(key,size)}<div class="tr-yr">'${awardEndYear(raw,true)}</div>${w.player?`<div class="tr-pl">${w.player}</div>`:''}</div>`;
      }).join('');
    };
  }catch(e){}
  try{
    trophyHtmlForManager=function(manager){
      const arr=managerAwards(manager);
      if(!arr.length)return '<div class="v16-award-empty">No trophy case items listed.</div>';
      return arr.map(a=>`<span class="v16-award-pill"><b>${esc(a.label)}</b>${a.season?` ${esc(awardEndYear(a.season,false))}`:''}${a.player?` · ${esc(a.player)}`:''}${a.team?` · ${esc(a.team)}`:''}</span>`).join('');
    };
  }catch(e){}
  try{if(typeof view!=='undefined'&&(view==='awards'||view==='managerrankings'))render();}catch(e){}
})();

;

