(function(){
  function removeCutFeatures(){
    document.querySelectorAll('#tabSalaryCap,#tabNhlAwards,.sports-crawl,#sportsCrawl,#sportsCrawlTrack,#sportsTickerV23,#v27LivewireBoard,.v27-livewire').forEach(el=>el.remove());
    document.querySelectorAll('button.tab').forEach(btn=>{
      const txt=(btn.textContent||'').replace(/\s+/g,' ').trim().toLowerCase();
      if(txt==='salary cap'||txt==='nhl awards') btn.remove();
    });
  }
  const noop=function(){removeCutFeatures();};
  window.loadTicker=window.updateTickerV16=window.updateTickerV17=window.updateTickerV18=window.updateTickerV19=window.updateTickerV20=window.updateTickerV21=window.updateTickerV22=window.updateTickerV23=window.updateTickerV24=window.updateLivewireFlipV24=noop;
  if(window.v57TickerTimer) clearInterval(window.v57TickerTimer);
  if(window.v61AwardTimer) clearInterval(window.v61AwardTimer);
  if(window.v61ForeverAwardTimer) clearInterval(window.v61ForeverAwardTimer);
  const priorCtrl=window.ctrl;
  if(typeof priorCtrl==='function'){
    window.ctrl=ctrl=function(){
      if(typeof view!=='undefined' && (view==='salarycap'||view==='nhlawards')) view='awards';
      const out=priorCtrl.apply(this,arguments);
      removeCutFeatures();
      return out;
    };
  }
  const priorRender=window.render;
  if(typeof priorRender==='function'){
    window.render=render=function(){
      if(typeof view!=='undefined' && (view==='salarycap'||view==='nhlawards')) view='awards';
      removeCutFeatures();
      return priorRender.apply(this,arguments);
    };
  }
  const priorSetView=window.setView;
  if(typeof priorSetView==='function'){
    window.setView=setView=function(v){
      if(v==='salarycap'||v==='nhlawards') v='awards';
      const out=priorSetView.call(this,v);
      removeCutFeatures();
      return out;
    };
  }
  const priorEnsure=window.ensureTabs;
  if(typeof priorEnsure==='function'){
    window.ensureTabs=function(){const out=priorEnsure.apply(this,arguments); removeCutFeatures(); return out;};
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',removeCutFeatures);
  else removeCutFeatures();
  setTimeout(removeCutFeatures,50); setTimeout(removeCutFeatures,300); setTimeout(removeCutFeatures,1200); setTimeout(removeCutFeatures,3500);
  try{new MutationObserver(removeCutFeatures).observe(document.documentElement,{childList:true,subtree:true});}catch(e){}
})();

;

(function(){
  const SLUG='forever';
  const POOL_LABEL='Forever Pool';
  const ACTIVE_KEY='fantraxActiveTeam:'+SLUG;
  function readActive(){
    try{return JSON.parse(sessionStorage.getItem(ACTIVE_KEY)||localStorage.getItem(ACTIVE_KEY)||'null');}catch(e){return null;}
  }
  function clearActive(){
    try{
      sessionStorage.removeItem('fantraxActiveTeam:bbl');
      sessionStorage.removeItem('fantraxActiveTeam:forever');
      localStorage.removeItem('fantraxActiveTeam:bbl');
      localStorage.removeItem('fantraxActiveTeam:forever');
      localStorage.removeItem('poolUpdates:v59:selectedTeam:bbl');
      localStorage.removeItem('poolUpdates:v59:selectedTeam:forever');
      localStorage.removeItem('poolUpdates:v58:selectedTeam:basement-bar-league');
      localStorage.removeItem('poolUpdates:v58:selectedTeam:forever-pool');
    }catch(e){}
  }
  function norm(x){return String(x||'').toLowerCase().replace(/&/g,'and').replace(/[^a-z0-9]+/g,'');}
  function saveActiveByKey(key){
    try{
      let name='';
      const list=(typeof TEAMS!=='undefined' && Array.isArray(TEAMS))?TEAMS:((typeof DATA!=='undefined'&&DATA&&Array.isArray(DATA.teams))?DATA.teams:[]);
      const t=list.find(x=>String((x&&x.id)||x.name)===String(key))||list.find(x=>norm(x&&x.name)===norm(key));
      if(t) name=String(t.name||'');
      if(!name) return;
      const payload=JSON.stringify({pool:SLUG,key:key,name:name,chosenAt:Date.now()});
      sessionStorage.setItem(ACTIVE_KEY,payload);
      localStorage.setItem(ACTIVE_KEY,payload);
    }catch(e){}
  }
  function showChip(active){
    if(!active||!active.name) return;
    if(document.querySelector('.v67-active-team-chip')) return;
    const host=document.querySelector('.filters')||document.querySelector('.tabs')||document.body.firstElementChild;
    const chip=document.createElement('div');
    chip.className='v67-active-team-chip';
    chip.innerHTML='Entered as <strong></strong> · Pool Updates will use this team';
    chip.querySelector('strong').textContent=active.name;
    if(host&&host.parentNode) host.parentNode.insertBefore(chip, host);
  }
  function openSelectedTrophy(){
    const active=readActive();
    if(!active||!active.name) return;
    showChip(active);
    try{ if(typeof window.setView==='function') window.setView('rankings'); else if(typeof setView==='function') setView('rankings'); }catch(e){}
    setTimeout(function(){
      const rows=Array.from(document.querySelectorAll('.row[onclick^="tog"]'));
      const idx=rows.findIndex(row=>{
        const img=row.querySelector('.r-tag img[alt]');
        const alt=img?img.getAttribute('alt'):'';
        return norm(alt)===norm(active.name) || norm(alt)===norm(active.key) || norm(active.name).includes(norm(alt)) || norm(alt).includes(norm(active.name));
      });
      if(idx<0) return;
      try{ if(typeof window.tog==='function') window.tog(idx); else rows[idx].click(); }catch(e){ rows[idx].click(); }
    }, 180);
  }
  document.querySelectorAll('.leave-bar-link.home-bar-link').forEach(a=>a.addEventListener('click', clearActive));
  const oldV59=window.v59SelectTeam;
  if(typeof oldV59==='function'){
    window.v59SelectTeam=function(key){saveActiveByKey(key); return oldV59.apply(this,arguments);};
  }
  const oldV58=window.v58SelectTeam;
  if(typeof oldV58==='function'){
    window.v58SelectTeam=function(key){saveActiveByKey(key); return oldV58.apply(this,arguments);};
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',openSelectedTrophy); else openSelectedTrophy();
  setTimeout(openSelectedTrophy, 700);
})();
